module logic;
use model {Summary,Job};
use util {reverse};

record MemberScan {pending:List<I64>,target:I64,found:Bool}
record Choice {found:Bool,id:I64,cost:I64,blocked:I64}
record ChoiceScan {pending:List<Job>,completed:List<I64>,budget:I64,best:Choice}
record RunState {jobs:List<Job>,completed:List<I64>,order:List<I64>,spent:I64,budget:I64,choice:Choice}

fn hasId(values:List<I64>,target:I64)->Bool {
 let final=fold(i in List::length(values),state:MemberScan=MemberScan {pending:values,target:target,found:false}) {
  MemberScan {pending:List::tail(state.pending),target:state.target,found:state.found || List::head(state.pending)==state.target}
 };
 final.found
}

fn dependenciesDone(deps:List<I64>,completed:List<I64>)->Bool {
 let final=fold(i in List::length(deps),state:MemberScan=MemberScan {pending:deps,target:0,found:true}) {
  MemberScan {pending:List::tail(state.pending),target:0,found:state.found && hasId(completed,List::head(state.pending))}
 };
 final.found
}

fn choose(jobs:List<Job>,completed:List<I64>,budget:I64)->Choice {
 let final=fold(i in List::length(jobs),state:ChoiceScan=ChoiceScan {pending:jobs,completed:completed,budget:budget,best:Choice {found:false,id:0,cost:0,blocked:0}}) {
  let job=List::head(state.pending);
  let unfinished=!hasId(state.completed,job.id);
  let blocked=if unfinished {state.best.blocked+1} else {state.best.blocked};
  let fits=if unfinished {dependenciesDone(job.deps,state.completed) && job.cost<=state.budget} else {false};
  let best=if fits && (!state.best.found || job.id<state.best.id) {
   Choice {found:true,id:job.id,cost:job.cost,blocked:blocked}
  } else {
   Choice {found:state.best.found,id:state.best.id,cost:state.best.cost,blocked:blocked}
  };
  ChoiceScan {pending:List::tail(state.pending),completed:state.completed,budget:state.budget,best:best}
 };
 final.best
}

fn run(jobs:List<Job>,budget:I64)->Summary {
 let initialChoice=choose(jobs,List::empty<I64>(),budget);
 let final=while(state:RunState=RunState {jobs:jobs,completed:List::empty<I64>(),order:List::empty<I64>(),spent:0,budget:budget,choice:initialChoice}; state.choice.found) {
  let completed=List::prepend(state.choice.id,state.completed);
  let order=List::prepend(state.choice.id,state.order);
  let spent=state.spent+state.choice.cost;
  RunState {jobs:state.jobs,completed:completed,order:order,spent:spent,budget:state.budget,choice:choose(state.jobs,completed,state.budget-spent)}
 };
 Summary {order:reverse(final.order),spent:final.spent,blocked:final.choice.blocked}
}

